/**
 * Top-level error visible across the FFI boundary.
 *
 * Variants are coarse on purpose -- Kotlin callers map these to UI
 * messages rather than inspecting nested causes. The `Internal`
 * variant absorbs anything we have not yet given a dedicated mapping
 * for, so adding new variants in `fetchit-core` does not break the
 * FFI contract.
 *
 * Field name `reason` (not `message`) is deliberate -- uniffi's
 * generated Kotlin bindings produce `class Variant(val message: String) :
 * Exception()` which collides with `kotlin.Throwable.message`.
 */
sealed class FetchitException: kotlin.Exception() {
    
    /**
     * The supplied address is not valid 64-character hex.
     */
    class InvalidAddress(
        
        /**
         * Human-readable diagnostic.
         */
        val `reason`: kotlin.String
        ) : FetchitException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * A network operation (connect, fetch, decode) failed.
     */
    class Network(
        
        /**
         * Human-readable diagnostic.
         */
        val `reason`: kotlin.String
        ) : FetchitException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * No registered handler claimed the fetched bytes.
     */
    class NoHandlerMatched(
        ) : FetchitException() {
        override val message
            get() = ""
    }
    
    /**
     * A handler accepted the bytes but failed to render.
     */
    class Render(
        
        /**
         * `ContentHandler::kind` of the failing handler.
         */
        val `kind`: kotlin.String, 
        
        /**
         * Human-readable diagnostic.
         */
        val `reason`: kotlin.String
        ) : FetchitException() {
        override val message
            get() = "kind=${ `kind` }, reason=${ `reason` }"
    }
    
    /**
     * Catch-all for newly-added `fetchit-core` errors not yet mapped
     * individually.
     */
    class Internal(
        
        /**
         * Human-readable diagnostic.
         */
        val `reason`: kotlin.String
        ) : FetchitException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FetchitException> {
        override fun lift(error_buf: RustBuffer.ByValue): FetchitException = FfiConverterTypeFetchitError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFetchitError : FfiConverterRustBuffer<FetchitException> {
    override fun read(buf: ByteBuffer): FetchitException {
        

        return when(buf.getInt()) {
            1 -> FetchitException.InvalidAddress(
                FfiConverterString.read(buf),
                )
            2 -> FetchitException.Network(
                FfiConverterString.read(buf),
                )
            3 -> FetchitException.NoHandlerMatched()
            4 -> FetchitException.Render(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            5 -> FetchitException.Internal(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FetchitException): ULong {
        return when(value) {
            is FetchitException.InvalidAddress -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is FetchitException.Network -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is FetchitException.NoHandlerMatched -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is FetchitException.Render -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`kind`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is FetchitException.Internal -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: FetchitException, buf: ByteBuffer) {
        when(value) {
            is FetchitException.InvalidAddress -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FetchitException.Network -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FetchitException.NoHandlerMatched -> {
                buf.putInt(3)
                Unit
            }
            is FetchitException.Render -> {
                buf.putInt(4)
                FfiConverterString.write(value.`kind`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FetchitException.Internal -> {
                buf.putInt(5)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Outcome of a durable join, surfaced to Android
 * ([`crate::ChatClient::join_group_durable`]). `Converged` carries the live
 * group; `Pending` carries only the group id -- the join is a durable intent
 * the resume pump completes when the owner is next reachable, so the shell
 * draws "joining…" instead of a failure. Mirrors
 * [`fetchit_chat::groups::JoinOutcome`].
 */
sealed class JoinOutcomeFfi {
    
    /**
     * Fully joined and keyed -- usable immediately.
     */
    data class Converged(
        /**
         * The joined group.
         */
